function AmbassadorApply({ showToast }) {
  const [form, setForm] = useState({
    name: "", email: "", role: "", organization: "", experience: "", helpWith: [], notes: "",
  });
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const update = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const toggleHelp = (h) =>
    setForm((f) => ({
      ...f,
      helpWith: f.helpWith.includes(h) ? f.helpWith.filter((x) => x !== h) : [...f.helpWith, h],
    }));

  const submit = (e) => {
    e.preventDefault();
    const errs = {};
    if (!form.name.trim()) errs.name = "Required";
    if (!form.email.trim()) errs.email = "Required";
    if (!form.role) errs.role = "Required";
    if (!form.experience) errs.experience = "Required";
    setErrors(errs);
    if (Object.keys(errs).length === 0) {
      setSubmitted(true);
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  if (submitted) {
    return (
      <div className="max-w-2xl mx-auto px-6 lg:px-10 py-24 text-center">
        <Check size={32} color={NAVY} className="mx-auto mb-4" />
        <h1 className="tf-serif text-3xl mb-3" style={{ color: NAVY }}>Thanks, {form.name.split(" ")[0] || "there"}</h1>
        <p className="text-sm leading-relaxed" style={{ color: INK_SOFT }}>
          This is a static mockup of the Ambassador application, for review only - nothing was
          actually sent or saved. On the live site, our team would follow up by email within 5
          working days.
        </p>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto px-6 lg:px-10 py-20">
      <Eyebrow>Community &amp; Network</Eyebrow>
      <h1 className="tf-serif text-4xl md:text-5xl mb-4" style={{ color: NAVY }}>Ready to help THINK FIRST grow?</h1>
      <p className="text-sm leading-relaxed mb-2" style={{ color: INK_SOFT }}>Tell us a bit about you.</p>
      <p className="text-xs mb-10" style={{ color: "#9AA3B2" }}>
        Illustrative mockup - not a live form yet, nothing is submitted anywhere.
      </p>

      <form onSubmit={submit} className="space-y-8">
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-sm font-medium block mb-1.5" style={{ color: NAVY }}>Name*</label>
            <input
              value={form.name}
              onChange={(e) => update("name", e.target.value)}
              className="w-full border rounded-lg px-3.5 py-2.5 text-sm"
              style={{ borderColor: errors.name ? PINK : "#D9DEE7" }}
              placeholder="Nguyen Van A"
            />
            {errors.name && <p className="text-xs mt-1" style={{ color: PINK }}>{errors.name}</p>}
          </div>
          <div>
            <label className="text-sm font-medium block mb-1.5" style={{ color: NAVY }}>Email*</label>
            <input
              type="email"
              value={form.email}
              onChange={(e) => update("email", e.target.value)}
              className="w-full border rounded-lg px-3.5 py-2.5 text-sm"
              style={{ borderColor: errors.email ? PINK : "#D9DEE7" }}
              placeholder="a.nguyen@university.edu.vn"
            />
            {errors.email && <p className="text-xs mt-1" style={{ color: PINK }}>{errors.email}</p>}
          </div>
        </div>

        <div>
          <label className="text-sm font-medium block mb-1.5" style={{ color: NAVY }}>Your role*</label>
          <div className="flex flex-wrap gap-2">
            {AMBASSADOR_ROLE_OPTIONS.map((r) => (
              <Pill key={r} plain active={form.role === r} onClick={() => update("role", r)}>{r}</Pill>
            ))}
          </div>
          {errors.role && <p className="text-xs mt-1.5" style={{ color: PINK }}>{errors.role}</p>}
        </div>

        <div>
          <label className="text-sm font-medium block mb-1.5" style={{ color: NAVY }}>Organization / community</label>
          <input
            value={form.organization}
            onChange={(e) => update("organization", e.target.value)}
            className="w-full border rounded-lg px-3.5 py-2.5 text-sm"
            style={{ borderColor: "#D9DEE7" }}
            placeholder="Optional - if you have one in mind"
          />
        </div>

        <div>
          <label className="text-sm font-medium block mb-1.5" style={{ color: NAVY }}>Have you experienced THINK FIRST before?*</label>
          <div className="flex flex-wrap gap-2">
            {AMBASSADOR_EXPERIENCE_OPTIONS.map((o) => (
              <Pill key={o} plain active={form.experience === o} onClick={() => update("experience", o)}>{o}</Pill>
            ))}
          </div>
          {errors.experience && <p className="text-xs mt-1.5" style={{ color: PINK }}>{errors.experience}</p>}
        </div>

        <div>
          <label className="text-sm font-medium block mb-1.5" style={{ color: NAVY }}>What would you like to help with?</label>
          <div className="flex flex-wrap gap-2">
            {AMBASSADOR_HELP_OPTIONS.map((h) => (
              <Pill key={h} plain active={form.helpWith.includes(h)} onClick={() => toggleHelp(h)}>{h}</Pill>
            ))}
          </div>
        </div>

        <div>
          <label className="text-sm font-medium block mb-1.5" style={{ color: NAVY }}>Anything else you'd like us to know?</label>
          <textarea
            value={form.notes}
            onChange={(e) => update("notes", e.target.value)}
            rows={4}
            className="w-full border rounded-lg px-3.5 py-2.5 text-sm"
            style={{ borderColor: "#D9DEE7" }}
          />
        </div>

        <button
          type="submit"
          className="w-full text-sm font-semibold px-5 py-3.5 rounded-full text-white"
          style={{ background: PINK }}
        >
          Submit my application
        </button>
      </form>
    </div>
  );
}

