/* ================= APP ================= */
function BackToTop() {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const onScroll = () => setVisible(window.scrollY > 500);
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  if (!visible) return null;
  return (
    <button
      onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
      aria-label="Back to top"
      className="md:hidden fixed bottom-5 right-5 z-40 w-11 h-11 rounded-full flex items-center justify-center shadow-lg"
      style={{ background: NAVY }}
    >
      <ArrowUp size={18} color="#fff" />
    </button>
  );
}

export default function App() {
  const [page, setPage] = useState("Home");
  const [lang, setLang] = useState("EN");
  const [toast, setToast] = useState("");

  const showToast = (msg) => {
    setToast(msg);
    window.clearTimeout(window.__tfToast);
    window.__tfToast = window.setTimeout(() => setToast(""), 3200);
  };

  const go = (p, anchor) => {
    setPage(p);
    if (anchor) {
      window.setTimeout(() => {
        const el = document.getElementById(anchor);
        if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
        else window.scrollTo({ top: 0, behavior: "smooth" });
      }, 60);
    } else {
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  return (
    <div className="min-h-screen bg-white" style={{ color: INK, fontFamily: "'Open Sauce Sans', sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=IBM+Plex+Mono:wght@500&display=swap');
        @import url('https://fonts.cdnfonts.com/css/open-sauce-sans');
        .tf-serif { font-family: 'Fraunces', serif; font-weight: 500; }
        .tf-mono { font-family: 'IBM Plex Mono', monospace; }
        .tf-spin { animation: tf-rotate 14s linear infinite; }
        @keyframes tf-rotate { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        details summary::-webkit-details-marker { display: none; }
        input:focus, textarea:focus, button:focus-visible {
          outline: 2px solid ${PINK};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .tf-spin { animation: none; }
        }
      `}</style>

      <Nav page={page} setPage={go} lang={lang} setLang={setLang} showToast={showToast} />

      {page === "Home" && <Home setPage={go} />}
      {page === "Learn" && <Learn />}
      {page === "Toolkit" && <Toolkit showToast={showToast} setPage={go} />}
      {page === "Pilot" && <Pilot showToast={showToast} />}
      {page === "Community" && <Community showToast={showToast} setPage={go} />}
      {page === "Ambassador" && <Ambassador setPage={go} />}
      {page === "AmbassadorApply" && <AmbassadorApply showToast={showToast} />}
      {page === "Download" && <DownloadPage showToast={showToast} />}
      {page === "About" && <About />}
      {page === "Contact" && <Contact showToast={showToast} />}

      <Footer setPage={go} />
      <Toast message={toast} />
      <BackToTop />
    </div>
  );
}
